# --- 나중에 짜기: 코드부터 ---

//  이미 있는 코드
public int calculateDiscountedPrice(int totalPrice, int memberLevel) {
    if (memberLevel == 1) return (int) (totalPrice * 0.95);
    if (memberLevel == 2) return (int) (totalPrice * 0.90);
    return totalPrice;
}

//  코드를 보고 테스트를 짠다

@Test void level1() {
    assertThat(calc.calculateDiscountedPrice(10000, 1)).isEqualTo(9500);
}
@Test void level2() {
    assertThat(calc.calculateDiscountedPrice(10000, 2)).isEqualTo(9000);
}
@Test void level0() {
    assertThat(calc.calculateDiscountedPrice(10000, 0)).isEqualTo(10000);
}

$ ./gradlew test --tests DiscountCalculatorTest

DiscountCalculatorTest > level1() PASSED
DiscountCalculatorTest > level2() PASSED
DiscountCalculatorTest > level0() PASSED

3 tests completed

#   전부 통과했다

#   커버리지도 100% 다

# --- 그런데 요구사항을 보면 ---

#   "회원 등급별 할인
#      일반(0)  0%
#      실버(1)  5%
#      골드(2)  10%
#      VIP(3)   15%
#    등급이 범위를 벗어나면 예외"

#   VIP 가 없다
#   음수 등급도 없다
#   등급 99 를 넣으면?

@Test void level3() {
    assertThat(calc.calculateDiscountedPrice(10000, 3)).isEqualTo(8500);
}
@Test void invalidLevel() {
    assertThatThrownBy(() -> calc.calculateDiscountedPrice(10000, 99))
        .isInstanceOf(IllegalArgumentException.class);
}

$ ./gradlew test --tests DiscountCalculatorTest

DiscountCalculatorTest > level3() FAILED
    expected: 8500
     but was: 10000

DiscountCalculatorTest > invalidLevel() FAILED
    Expecting code to raise a throwable.

